=Analyze this JD against my resume keywords.

<job_description>
{{ $json.jobTitle }} | {{ $json.companyName }}
{{ $json.url }}
{{ ($json.description || '').slice(0, 6000) }}
Detected skills: {{ ($json.skills_detected || []).join(', ') }}
</job_description>

<resume_keywords>
{{ Object.entries($('Get Json from MetaData').first().json.data).map(([track, files]) => Object.entries(files).map(([f, kws]) => `${track}/${f}: ${kws.join(', ')}`).join('\n')).join('\n') }}
