parameters.jsCode:
const list = $input.first().json.data || [];

const companyByUrl = {};
for (const j of $('LinkedIn Jobs & Search URL Scraper').all()) {
  companyByUrl[j.json.url] = j.json.companyName || j.json.company_name || '';
}

const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const parse = s => {
  try {
    return JSON.parse(String(s).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim());
  } catch (e) { return null; }
};

const ok = [];
let failed = 0;
for (const it of list) {
  const r = parse(it.output);
  if (r) ok.push(r); else failed++;
}
ok.sort((a, b) => (Number(b.match_score) || 0) - (Number(a.match_score) || 0));

const score = s => {
  const n = Number(s) || 0;
  const color = n >= 70 ? '#1a7f37' : n >= 40 ? '#b7791f' : '#c0392b';
  return `<b style="color:${color}">${n}</b>`;
};

const rows = ok.map((r, i) => {
  const mustMissing = (r.missing || []).filter(m => m.priority === 'must_have').slice(0, 6).map(m => esc(m.keyword)).join(', ');
  const company = esc(companyByUrl[r.job_url] || '');
  const yrs = r.min_years_required != null ? `${esc(r.min_years_required)}+ yrs` : '-';
  const link = r.job_url ? `<a href="${esc(r.job_url)}">Open</a>` : '';
  return `<tr>
    <td>${i + 1}</td>
    <td>${score(r.match_score)}</td>
    <td>${esc(r.role_title)}<br><small>${company}</small></td>
    <td>${esc(r.best_resume)}</td>
    <td>${yrs}</td>
    <td>${esc((r.matched || []).map(m => m.keyword).slice(0, 8).join(', '))}</td>
    <td>${mustMissing}</td>
    <td>${link}</td>
  </tr>`;
}).join('');

const style = 'border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px';
const cell = 'border:1px solid #ddd;padding:6px;vertical-align:top;text-align:left';

const html = ok.length === 0
  ? '<p>No jobs analysed today.</p>'
  : `<h3>Daily job matches (${ok.length})</h3>
<table style="${style}">
<style>td,th{${cell}}th{background:#f3f4f6}</style>
<tr><th>#</th><th>Score</th><th>Role</th><th>Best resume</th><th>Exp</th><th>Matched</th><th>Missing (must-have)</th><th>Link</th></tr>
${rows}
</table>${failed ? `<p><small>${failed} job(s) failed analysis.</small></p>` : ''}`;

return [{ json: { html, count: ok.length, failed } }];
